contains
   pure function bundled_map(i) result(rgb)
   !< The i-th bundled map's samples (RGB in [0, 1], one column each); zeros for an i out of range.
   integer(int32), intent(in) :: i                   !< Map (1 .. BUNDLED_COUNT).
   real(real64)               :: rgb(3, BUNDLED_SAMPLES) !< Samples.

   select case (i)
   case (1_int32)
      rgb = MAP_BALANCE
   case (2_int32)
      rgb = MAP_BATLOW
   case (3_int32)
      rgb = MAP_CIVIDIS
   case (4_int32)
      rgb = MAP_COOL_WARM
   case (5_int32)
      rgb = MAP_CURL
   case (6_int32)
      rgb = MAP_DEEP
   case (7_int32)
      rgb = MAP_HALINE
   case (8_int32)
      rgb = MAP_INFERNO
   case (9_int32)
      rgb = MAP_MAGMA
   case (10_int32)
      rgb = MAP_ROMA
   case (11_int32)
      rgb = MAP_ROMAO
   case (12_int32)
      rgb = MAP_THERMAL
   case (13_int32)
      rgb = MAP_TURBO
   case (14_int32)
      rgb = MAP_VIK
   case default
      rgb = 0.0_R
   endselect
   endfunction bundled_map
